    <div className=\"table-toolbar\"><TextInput className=\"search\" size=\"l\" placeholder=\"Найти заказ, клиента или email\" aria-label=\"Поиск заказов\" value={query} onUpdate={setQuery} hasClear startContent={<Icon data={Magnifier} size={17}/>}/><Button view=\"outlined\" size=\"l\" selected={showFilters} onClick={() => setShowFilters(v => "'!v)}><Icon data={Sliders} size={16}/>Фильтры{payment !== '"'all' && ' · 1'}</Button><div className=\"toolbar-spacer\"/><Button view={grouped ? 'flat-action' : 'outlined'} size=\"l\" onClick={() => {setGrouped(v => "'!v); setExpanded(true);}}><Icon data={Layers} size={16}/><span className="group-label">По статусу</span><Icon data={ChevronDown} size={12}/></Button><Button view="outlined" size="l" aria-label="Настроить колонки" title="Настроить колонки" onClick={() => setModal('"'columns')}><Icon data={LayoutColumns3} size={17}/></Button></div>
    {showFilters && <div className=\"filter-row\"><span className=\"muted\">Оплата</span><Select value={[payment]} onUpdate={v => setPayment(v[0])} options={[{value:'all', content:'Любая оплата'}, {value:'paid', content:'Оплаченные'}, {value:'unpaid', content:'Ожидают оплаты'}]}/><Button view=\"flat\" onClick={resetFilters}>Сбросить фильтры</Button></div>}
    {selectedOrders.length > 0 && <div className=\"selection-toolbar\"><strong>Выбрано: {selectedOrders.length}</strong><Button size=\"s\" view=\"outlined\" onClick={exportOrders}>Экспортировать</Button><DropdownMenu items={statuses.map(s => ({text: statusInfo[s].short, action: () => {setOrders(prev => prev.map(o => rowSelection[o.id] ? {...o, status:s} : o)); setRowSelection({}); setToast('Статусы выбранных заказов обновлены');}}))} switcher={<Button size=\"s\" view=\"outlined\">Изменить статус <Icon data={ChevronDown} size={12}/></Button>}/><Button view=\"flat\" size=\"s\" onClick={() => setRowSelection({})} aria-label=\"Снять выделение\"><Icon data={Xmark} size={14}/></Button></div>}
    <div className=\"table-scroll\"><ColumnReorderingProvider table={table} onReorder={({columnOrder: next}) => setColumnOrder(next)}><Table table={table} className=\"orders-table\" size=\"m\" verticalAlign=\"middle\" headerCellClassName=\"order-header-cell\" cellClassName=\"order-cell\" groupHeaderClassName=\"order-group\" rowClassName={row => row?.getIsSelected() ? 'selected-row' : ''} getIsGroupHeaderRow={row => Boolean(row.original.children)} getGroupTitle={row => <span className=\"group-title\"><span className={"'`group-dot ${row.original.status}`}/>{statusInfo[row.original.status].label}<span className="group-count">{row.subRows.length}</span><span className="group-total">{money(row.subRows.reduce((sum,r) => sum+r.original.amount,0))}</span></span>} emptyContent={<div className="empty-state"><Icon data={Magnifier} size={28}/><Text variant="subheader-2">Заказы не найдены</Text><span className="muted">Попробуйте другой запрос или измените фильтры.</span><Button view="outlined" onClick={resetFilters}>Сбросить фильтры</Button></div>}/></ColumnReorderingProvider></div>
    <div className="table-footer"><span className="muted">Показано {filtered.length ? (currentPage-1)*pageSize+1 : 0}–{Math.min(currentPage*pageSize, filtered.length)} из {filtered.length} заказов</span><div className="pagination"><span className="muted per-page-label">На странице</span><Select aria-label="Заказов на странице" value={[String(pageSize)]} onUpdate={v => setPageSize(Number(v[0]))} options={[12,24,48].map(n => ({value:String(n),content:String(n)}))}/><div className="page-buttons"><Button view="flat" disabled={currentPage === 1} aria-label="Предыдущая страница" onClick={() => {setPage(currentPage-1); setRowSelection({});}}><Icon data={ChevronLeft} size={14}/></Button>{Array.from({length: Math.min(3,pageCount)}, (_,i) => i+1).map(p => <Button key={p} view={currentPage === p ? '"'flat-action':'flat'} selected={currentPage === p} onClick={() => {setPage(p); setRowSelection({});}}>{p}</Button>)}{pageCount > 4 && <span className=\"pagination-dots\">…</span>}{pageCount > 3 && <Button view={currentPage > 3 ? 'flat-action':'flat'} selected={currentPage > 3} onClick={() => {setPage(pageCount); setRowSelection({});}}>{currentPage > 3 && currentPage "'!== pageCount ? currentPage : pageCount}</Button>}<Button view="flat" disabled={currentPage === pageCount} aria-label="Следующая страница" onClick={() => {setPage(currentPage+1); setRowSelection({});}}><Icon data={ChevronRight} size={14}/></Button></div></div></div></section><div className="page-footnote"><span><Icon data={CircleCheck} size={14}/>Все изменения сохраняются в текущей сессии</span><span>Перетащите заголовок, чтобы изменить порядок колонок</span></div></>}
    {section === '"'users' && <section className=\"users-grid\">{Array.from(new Map(orders.map(o => [o.email,o])).values()).map(o => <div className=\"user-card\" key={o.email}><Customer order={o}/><div className=\"user-card-bottom\"><span className=\"muted\">{orders.filter(a => a.email === o.email).length} заказов</span><strong>{money(orders.filter(a => a.email === o.email).reduce((s,a) => s+a.amount,0))}</strong></div><Button view=\"outlined\" onClick={() => {setQuery(o.email); setStatus('all'); setPayment('all'); setSection('orders');}}>Посмотреть заказы</Button></div>)}</section>}
    {section === 'settings' && <section className=\"settings-panel\"><Text variant=\"subheader-3\">Рабочее пространство</Text><label>Название магазина<TextInput size=\"l\" value={storeName} onUpdate={v => {setStoreName(v); setSavedSettings(false);}}/></label><Checkbox checked={notifications} onUpdate={setNotifications}>Уведомления о новых заказах</Checkbox><Button size=\"l\" view=\"action\" onClick={() => {setSavedSettings(true); setToast('Настройки сохранены в текущей сессии');}}>Сохранить изменения</Button>{savedSettings && <span className=\"paid\">Настройки сохранены</span>}</section>}
    </main><Modal open={modal "'!== null} onClose={() => setModal(null)} aria-label={modal === '"'create' ? 'Новый заказ' : 'Информация'}><div className=\"modal-content\"><Button view=\"flat\" className=\"modal-close\" aria-label=\"Закрыть\" onClick={() => setModal(null)}><Icon data={Xmark} size={18}/></Button>
    {modal === 'create' && <form onSubmit={createOrder} className=\"modal-form\"><Text variant=\"header-1\">Новый заказ</Text><p className=\"muted\">Добавьте заказ в рабочее пространство.</p><label>Имя клиента<TextInput autoFocus size=\"l\" value={form.name} onUpdate={name => setForm({...form,name})} placeholder=\"Анна Смирнова\"/></label><label>Email<TextInput type=\"email\" size=\"l\" value={form.email} onUpdate={email => setForm({...form,email})} placeholder=\"client@example.com\"/></label><label>Сумма заказа, ₽<TextInput type=\"number\" size=\"l\" value={form.amount} onUpdate={amount => setForm({...form,amount})} placeholder=\"0\" controlProps={{min:0.01, step:0.01}}/></label>{formError && <span className=\"form-error\" role=\"alert\">{formError}</span>}<Button type=\"submit\" size=\"l\" view=\"action\">Создать заказ</Button></form>}
    {modal === 'columns' && <div className=\"modal-form\"><Text variant=\"header-1\">Колонки таблицы</Text><p className=\"muted\">Выберите колонки. Их порядок можно менять перетаскиванием заголовков.</p>{table.getAllLeafColumns().filter(c => "'!['"'_select','actions'].includes(c.id)).map(c => <Checkbox key={c.id} checked={c.getIsVisible()} onUpdate={v => c.toggleVisibility(v)}>{String(c.columnDef.header)}</Checkbox>)}<Button view=\"outlined\" onClick={() => {setColumnVisibility({}); setColumnOrder(['_select','id','name','date','amount','status','paid','actions']);}}>Восстановить по умолчанию</Button><Button view=\"action\" onClick={() => setModal(null)}>Готово</Button></div>}
    {modal === 'detail' && detail && <div className=\"modal-form\"><Text variant=\"header-1\">Заказ #{detail.id}</Text><Customer order={detail}/><div className=\"detail-line\"><span>Дата</span><strong>{formatDate(detail.date)} 2026, {detail.time}</strong></div><div className=\"detail-line\"><span>Сумма</span><strong>{money(detail.amount)}</strong></div><div className=\"detail-line\"><span>Товаров</span><strong>{detail.items}</strong></div><div className=\"detail-line\"><span>Оплата</span><strong>{detail.paid ? 'Оплачен':'Ожидает оплаты'}</strong></div><label>Статус заказа<Select width=\"max\" size=\"l\" value={[orders.find(o => o.id === detail.id)?.status || detail.status]} onUpdate={v => changeStatus(detail.id, v[0] as Status)} options={statuses.map(s => ({value:s,content:statusInfo[s].short}))}/></label></div>}
    {modal === 'notifications' && <div className=\"modal-form\"><Text variant=\"header-1\">Уведомления</Text>{notifications ? orders.filter(o => o.status === 'new').slice(0,3).map(o => <div className=\"notification-item\" key={o.id}><span className=\"metric-icon purple\"><Icon data={ShoppingBag} size={18}/></span><div><strong>Новый заказ #{o.id}</strong><p className=\"muted\">{o.name} · {money(o.amount)}</p></div></div>) : <p className=\"muted\">Уведомления отключены в настройках.</p>}</div>}
    {modal === 'help' && <div className=\"modal-form\"><Text variant=\"header-1\">Как работать с заказами</Text><p>Выделяйте заказы флажками, чтобы экспортировать их или изменить статус сразу у нескольких.</p><p>Перетаскивайте заголовки колонок для изменения порядка. Кнопка «По статусу» включает группировку, а стрелка у группы сворачивает её.</p><p>Используйте поиск по номеру, имени или email. Дополнительные фильтры позволяют отобрать заказы по оплате.</p></div>}
    {modal === 'plan' && <div className=\"modal-form\"><span className=\"pro-badge\">FORMA PRO</span><Text variant=\"header-1\">Больше места для роста</Text><p className=\"muted\">Расширенная аналитика, командная работа и автоматизация обработки заказов.</p><p>В демонстрационном пространстве все основные функции управления заказами уже доступны. Для подключения тарифа потребуется интеграция с вашим сервисом.</p><Button view=\"action\" onClick={() => setModal(null)}>Продолжить работу</Button></div>}
    {modal === 'profile' && <div className=\"modal-form\"><span className=\"avatar admin-avatar\">АК</span><Text variant=\"header-1\">Александр К.</Text><span className=\"muted\">Администратор · {storeName}</span><Button view=\"outlined\" onClick={() => {setModal(null); setSection('settings');}}>Настройки рабочего пространства <Icon data={ArrowRightFromSquare} size={16}/></Button></div>}
    </div></Modal>{toast && <div className=\"toast\" role=\"status\"><Icon data={CircleCheck} size={18}/>{toast}</div>}</div>}/>;
}
EOF"

args.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root {
  --g-color-base-brand: var(--g-color-base-utility-heavy);
  --g-color-base-brand-hover: var(--g-color-base-utility-heavy-hover);
  --g-color-base-selection: var(--g-color-base-utility-light);
  --g-color-base-selection-hover: var(--g-color-base-utility-light-hover);
  --g-color-line-brand: var(--g-color-line-utility);
  --g-color-text-brand: var(--g-color-text-utility);
  --g-color-text-brand-heavy: var(--g-color-text-utility-heavy);
  --g-color-text-brand-contrast: var(--g-color-text-light-primary);
  --g-color-text-link: var(--g-color-text-utility);
  --g-color-text-link-hover: var(--g-color-text-utility-heavy);
  --g-color-line-focus: var(--g-color-line-utility);
  --g-font-family-sans: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-body-font-family: var(--g-font-family-sans);
  --g-text-header-font-family: var(--g-font-family-sans);
  --g-text-subheader-font-family: var(--g-font-family-sans);
  --g-text-display-font-family: var(--g-font-family-sans);
  --g-button-border-radius: var(--g-border-radius-m);
}
* {box-sizing: border-box;}
body {margin: 0; min-width: 360px; -webkit-font-smoothing: antialiased;}
button, input {font-family: inherit;}
.app-shell {
  --gn-aside-header-expanded-background-color: var(--g-color-base-background);
  --gn-aside-header-background-color: var(--g-color-base-background);
  --gn-aside-header-item-current-background-color: var(--g-color-base-selection);
  --gn-aside-header-item-current-background-color-hover: var(--g-color-base-selection-hover);
  --gn-aside-header-item-current-text-color: var(--g-color-text-brand);
  --gn-aside-header-item-current-icon-color: var(--g-color-text-brand);
  --gn-aside-header-item-text-color: var(--g-color-text-complementary);
  --gn-aside-header-item-icon-color: var(--g-color-text-secondary);
  --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);
  --gn-aside-header-divider-vertical-color: var(--g-color-line-generic);
}
.brand-word {font-size: 30px; font-weight: 750; letter-spacing: -1.4px; color: var(--g-color-text-primary);}
.brand-dot {color: var(--g-color-text-brand);}
.workspace {display:flex; align-items:center; gap:var(--g-spacing-3); margin:var(--g-spacing-5) var(--g-spacing-4) var(--g-spacing-7); padding:var(--g-spacing-3); border:1px solid var(--g-color-line-generic); border-radius:var(--g-border-radius-l);}
.workspace-compact {padding:var(--g-spacing-2) 0; margin:var(--g-spacing-4) auto; border:0; justify-content:center;}
.store-avatar {display:grid;place-items:center;width:32px;height:32px;flex-shrink:0;border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-m);font-weight:600;background:var(--g-color-base-generic-ultralight);}
.workspace-name {flex:1;min-width:0;font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.workspace-name span {display:block;font-size:10px;font-weight:400;margin-top:var(--g-spacing-1);}
.muted {color:var(--g-color-text-secondary);}
.nav-count {background:var(--g-color-base-utility-light);color:var(--g-color-text-brand);font-size:11px;font-weight:600;padding:var(--g-spacing-half) var(--g-spacing-2);border-radius:var(--g-border-radius-s);}
.help-card {margin:var(--g-spacing-4) var(--g-spacing-2) var(--g-spacing-6);padding:var(--g-spacing-4);background:linear-gradient(125deg,var(--g-color-base-utility-light),var(--g-color-base-generic-ultralight));border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);}
.help-icon {color:var(--g-color-text-brand);display:block;margin-bottom:var(--g-spacing-3);}
.help-title {font-weight:600;font-size:13px;}
.help-card p {font-size:11px;line-height:1.7;color:var(--g-color-text-secondary);margin:var(--g-spacing-2) 0 var(--g-spacing-4);}
.help-card .g-button {--g-button-background-color:var(--g-color-base-background);font-size:11px;}
.profile {display:flex;align-items:center;gap:var(--g-spacing-3);padding:var(--g-spacing-5) var(--g-spacing-2) var(--g-spacing-2);margin-top:var(--g-spacing-3);border-top:1px solid var(--g-color-line-generic);}
.profile>div {flex:1;min-width:0;}
.profile strong {font-size:12px;font-weight:600;}
.profile .muted {font-size:10px;display:block;margin-top:var(--g-spacing-1);}
.profile-compact {justify-content:center;padding-inline:0;}
.avatar {display:inline-flex;align-items:center;justify-content:center;width:33px;height:33px;border-radius:50%;font-size:10px;font-weight:600;flex-shrink:0;background:var(--g-color-base-utility-light);color:var(--g-color-text-utility);}
.avatar-0 {background:var(--g-color-base-warning-light);color:var(--g-color-text-warning-heavy);}
.avatar-1 {background:var(--g-color-base-info-light);color:var(--g-color-text-info);}
.avatar-2 {background:var(--g-color-base-positive-light);color:var(--g-color-text-positive);}
.avatar-3 {background:var(--g-color-base-utility-light);color:var(--g-color-text-utility);}
.avatar-4 {background:var(--g-color-base-danger-light);color:var(--g-color-text-danger);}
.admin-avatar,.top-avatar {background:var(--g-color-base-warning-light);color:var(--g-color-text-warning-heavy);border:3px solid var(--g-color-base-background);box-shadow:0 0 0 1px var(--g-color-line-generic);}
.page {height:100dvh;overflow-y:auto;min-width:0;background:var(--g-color-base-generic-ultralight);}
.topbar {height:76px;display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);padding:0 var(--g-spacing-8);background:var(--g-color-base-background);border-bottom:1px solid var(--g-color-line-generic);}
.breadcrumbs {display:flex;align-items:center;gap:var(--g-spacing-4);color:var(--g-color-text-secondary);font-size:12px;}
.breadcrumbs strong {color:var(--g-color-text-primary);font-weight:500;}
.topbar-right {display:flex;align-items:center;gap:var(--g-spacing-3);flex-shrink:0;}
.live-label {display:flex;align-items:center;gap:var(--g-spacing-2);font-size:11px;color:var(--g-color-text-secondary);}
.live-label .status-dot {background:var(--g-color-text-positive);}
.topbar-divider {width:1px;height:22px;background:var(--g-color-line-generic);margin:0 var(--g-spacing-2);}
.notification-button {position:relative;}
.notification-dot {position:absolute;right:8px;top:5px;width:5px;height:5px;background:var(--g-color-text-brand);border-radius:50%;}
.main {padding:var(--g-spacing-8);max-width:1700px;margin:0 auto;}
.page-heading {display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);margin-bottom:var(--g-spacing-7);}
.eyebrow {font-size:9px;letter-spacing:1.6px;font-weight:600;color:var(--g-color-text-secondary);margin-bottom:var(--g-spacing-3);}
.page-heading h1 {margin:0;font-weight:650;letter-spacing:-.8px;}
.page-description {color:var(--g-color-text-secondary);font-size:12px;margin:var(--g-spacing-3) 0 0;line-height:1.6;}
.heading-actions {display:flex;gap:var(--g-spacing-3);flex-shrink:0;padding-top:var(--g-spacing-3);}
.heading-actions .g-button {font-size:12px;}
.metrics {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--g-spacing-4);margin-bottom:var(--g-spacing-7);}
.metric {padding:var(--g-spacing-5);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);background:var(--g-color-base-background);box-shadow:0 2px 3px var(--g-color-sfx-shadow);}
.metric-top {display:flex;justify-content:space-between;align-items:center;gap:var(--g-spacing-2);font-size:12px;color:var(--g-color-text-complementary);}
.metric-icon {display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:var(--g-border-radius-m);flex-shrink:0;}
.purple {background:var(--g-color-base-utility-light);color:var(--g-color-text-utility);}
.green {background:var(--g-color-base-positive-light);color:var(--g-color-text-positive);}
.orange {background:var(--g-color-base-warning-light);color:var(--g-color-text-warning-heavy);}
.blue {background:var(--g-color-base-info-light);color:var(--g-color-text-info);}
.metric-value {font-size:28px;line-height:1.3;letter-spacing:-.8px;font-weight:600;margin:var(--g-spacing-3) 0;white-space:nowrap;}
.metric-bottom {display:flex;align-items:center;gap:var(--g-spacing-2);font-size:10px;white-space:nowrap;}
.growth {display:inline-flex;align-items:center;gap:var(--g-spacing-1);font-weight:500;color:var(--g-color-text-positive);}
.orders-panel {border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);background:var(--g-color-base-background);overflow:hidden;box-shadow:0 2px 3px var(--g-color-sfx-shadow);}
.panel-heading {display:flex;align-items:center;justify-content:space-between;padding:var(--g-spacing-5) var(--g-spacing-5) var(--g-spacing-3);gap:var(--g-spacing-3);}
.panel-title {display:flex;align-items:center;gap:var(--g-spacing-3);}
.panel-title .g-text {font-size:16px;}
.count-badge {background:var(--g-color-base-generic);color:var(--g-color-text-secondary);font-size:10px;padding:var(--g-spacing-half) var(--g-spacing-2);border-radius:var(--g-border-radius-s);}
.period-select {display:flex;align-items:center;gap:var(--g-spacing-1);color:var(--g-color-text-complementary);}
.status-tabs {display:flex;gap:var(--g-spacing-5);border-bottom:1px solid var(--g-color-line-generic);padding:0 var(--g-spacing-5);overflow-x:auto;}
.status-tab.g-button {height:49px;--g-button-padding:0;--g-button-background-color-hover:transparent;--g-button-background-color:transparent;--g-button-border-radius:0;--g-button-text-color:var(--g-color-text-secondary);font-size:12px;border-bottom:2px solid transparent;flex-shrink:0;}
.status-tab.active.g-button {--g-button-text-color:var(--g-color-text-brand);border-bottom-color:var(--g-color-text-brand);}
.tab-count {font-size:10px;display:inline-flex;padding:0 var(--g-spacing-1);margin-left:var(--g-spacing-2);line-height:17px;background:var(--g-color-base-generic);border-radius:var(--g-border-radius-s);}
.active .tab-count {background:var(--g-color-base-selection);}
.table-toolbar {display:flex;align-items:center;gap:var(--g-spacing-3);padding:var(--g-spacing-4) var(--g-spacing-5);}
.search {max-width:330px;flex:1;min-width:160px;--g-text-input-border-color:var(--g-color-line-generic);}
.search .g-icon {color:var(--g-color-text-hint);margin-left:var(--g-spacing-1);}
