.user-card-bottom {display:flex;justify-content:space-between;margin:var(--g-spacing-5) 0;font-size:12px;}
.settings-panel {max-width:560px;display:flex;flex-direction:column;align-items:flex-start;gap:var(--g-spacing-6);padding:var(--g-spacing-7);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);background:var(--g-color-base-background);}
