.help-card {margin:var(--g-spacing-4) var(--g-spacing-2) var(--g-spacing-6);padding:var(--g-spacing-4);background:linear-gradient(125deg,var(--g-color-base-utility-light),var(--g-color-base-generic-ultralight));border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);}
