.notification-button {position:relative;}
.notification-dot {position:absolute;right:8px;top:5px;width:5px;height:5px;background:var(--g-color-text-brand);border-radius:50%;}
.main {padding:var(--g-spacing-8);max-width:1700px;margin:0 auto;}
.page-heading {display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);margin-bottom:var(--g-spacing-7);}
